CREATE TYPE "partner_status" AS ENUM ('active','inactive','pending');
CREATE TYPE "partner_user_role" AS ENUM ('partner','admin','executive');
CREATE TYPE "enquiry_product" AS ENUM ('jet_card','club_membership','charter','access_partners','general');
CREATE TYPE "enquiry_status" AS ENUM ('pending','synced','failed','stale');
CREATE TYPE "document_category" AS ENUM ('agreement','compliance','brand_asset','sales_collateral','guideline','other');
CREATE TYPE "document_visibility" AS ENUM ('private','shared');
CREATE TABLE "partners" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"name" text NOT NULL,"org" text,"email" text NOT NULL UNIQUE,"status" partner_status NOT NULL DEFAULT 'pending',"commission_rate" numeric(5,2),"commission_terms" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "partner_users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"partner_id" uuid REFERENCES "partners"("id") ON DELETE CASCADE,"name" text,"email" text NOT NULL UNIQUE,"email_verified" timestamptz,"image" text,"role" partner_user_role NOT NULL DEFAULT 'partner',"status" partner_status NOT NULL DEFAULT 'pending',"aup_accepted_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "accounts" ("user_id" uuid NOT NULL REFERENCES "partner_users"("id") ON DELETE CASCADE,"type" text NOT NULL,"provider" text NOT NULL,"provider_account_id" text NOT NULL,"refresh_token" text,"access_token" text,"expires_at" integer,"token_type" text,"scope" text,"id_token" text,"session_state" text,PRIMARY KEY("provider","provider_account_id"));
CREATE TABLE "sessions" ("session_token" text PRIMARY KEY,"user_id" uuid NOT NULL REFERENCES "partner_users"("id") ON DELETE CASCADE,"expires" timestamptz NOT NULL);
CREATE TABLE "verification_tokens" ("identifier" text NOT NULL,"token" text NOT NULL,"expires" timestamptz NOT NULL,PRIMARY KEY("identifier","token"));
CREATE TABLE "enquiries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"correlation_id" uuid NOT NULL DEFAULT gen_random_uuid(),"partner_id" uuid NOT NULL REFERENCES "partners"("id"),"submitted_by" uuid NOT NULL REFERENCES "partner_users"("id"),"product" enquiry_product NOT NULL,"status" enquiry_status NOT NULL DEFAULT 'pending',"ghl_opportunity_id" text,"ghl_pipeline_id" text,"payload" jsonb NOT NULL,"submitted_at" timestamptz NOT NULL DEFAULT now(),"confirmed_at" timestamptz,"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "enquiries_correlation_id_idx" ON "enquiries"("correlation_id");
CREATE TABLE "documents" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"partner_id" uuid REFERENCES "partners"("id"),"category" document_category NOT NULL,"file_key" text NOT NULL,"file_name" text NOT NULL,"file_size" integer,"mime_type" text,"uploaded_by" uuid NOT NULL REFERENCES "partner_users"("id"),"visibility" document_visibility NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "audit_log" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"actor_id" uuid REFERENCES "partner_users"("id"),"action" text NOT NULL,"entity_type" text NOT NULL,"entity_id" uuid,"before" jsonb,"after" jsonb,"ip_address" text,"created_at" timestamptz NOT NULL DEFAULT now());
